Step 2 — server/database/schema.sql: Create 11 tables with these exact definitions:
  resources(id TEXT PK, type TEXT, name TEXT, description TEXT, connected INTEGER DEFAULT 1, model TEXT, model_version TEXT, last_sync TEXT, requests_today INTEGER DEFAULT 0, total_requests INTEGER DEFAULT 0, api_status TEXT DEFAULT 'Operational', icon TEXT, rules TEXT);
  security_models(id TEXT PK, name TEXT, version TEXT, status TEXT DEFAULT 'Active', resource TEXT, training_samples INTEGER DEFAULT 0, detection_accuracy REAL DEFAULT 90.0, last_trained TEXT, attacks_detected INTEGER DEFAULT 0, training_history TEXT, attack_categories TEXT, progress INTEGER DEFAULT 0);
  prompts(id TEXT PK, prompt TEXT NOT NULL, resource TEXT, status TEXT DEFAULT 'Allowed', risk TEXT DEFAULT 'Low', time TEXT, detection_layer TEXT, attack_type TEXT, blocked_reason TEXT, created_at INTEGER DEFAULT (strftime('%s','now')));
  security_rules(id TEXT PK, resource_id TEXT REFERENCES resources(id), rule TEXT NOT NULL, active INTEGER DEFAULT 1);
  attack_tests(id TEXT PK, name TEXT, description TEXT, severity TEXT, icon TEXT);
  research_topics(id TEXT PK, title TEXT, description TEXT, severity TEXT, related_resource TEXT, attack_examples TEXT, detection_strategies TEXT);
  admin_reviews(id TEXT PK, prompt_id TEXT REFERENCES prompts(id), prompt TEXT NOT NULL, resource TEXT, detection_layer TEXT, risk TEXT, submitted TEXT, status TEXT DEFAULT 'Pending Review', analysis TEXT, notes TEXT, classification TEXT, category TEXT);
  training_samples(id TEXT PK, prompt TEXT NOT NULL, resource TEXT, attack_type TEXT, classification TEXT, source_review_id TEXT, created_at INTEGER DEFAULT (strftime('%s','now')));
  training_jobs(id TEXT PK, model_id TEXT REFERENCES security_models(id), model_name TEXT, resource TEXT, status TEXT DEFAULT 'Queued', progress INTEGER DEFAULT 0, dataset TEXT, dataset_size INTEGER DEFAULT 0, started_at INTEGER, completed_at INTEGER, created_at INTEGER DEFAULT (strftime('%s','now')));
  security_logs(id TEXT PK, title TEXT, resource TEXT, detail TEXT, risk TEXT, time TEXT, category TEXT, prompt_id TEXT, created_at INTEGER DEFAULT (strftime('%s','now')));
  settings(key TEXT PK, value TEXT);
